CREATE TABLE IF NOT EXISTS businesses (id text PRIMARY KEY, name text NOT NULL, business_type text NOT NULL, timezone text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS branches (id text PRIMARY KEY, business_id text NOT NULL REFERENCES businesses(id), name text NOT NULL, location_label text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reviews (id text PRIMARY KEY, business_id text NOT NULL REFERENCES businesses(id), branch_id text NOT NULL REFERENCES branches(id), source text NOT NULL, source_review_id text NOT NULL, rating integer NOT NULL CHECK (rating BETWEEN 1 AND 5), reviewed_at timestamptz NOT NULL, original_text text NOT NULL, is_synthetic boolean NOT NULL, processing_status text NOT NULL DEFAULT 'pending', language text NOT NULL DEFAULT 'unknown', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(business_id, source, source_review_id));
ALTER TABLE reviews ADD COLUMN IF NOT EXISTS processing_stage text;
CREATE INDEX IF NOT EXISTS reviews_branch_idx ON reviews(branch_id);
CREATE TABLE IF NOT EXISTS analysis_runs (id text PRIMARY KEY, review_id text NOT NULL REFERENCES reviews(id), decision text NOT NULL, screening_provider text NOT NULL, screening_model text, extraction_provider text, extraction_model text, matching_provider text, matching_model text, prompt_version text NOT NULL, mode text NOT NULL, safe_error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS observations (id text PRIMARY KEY, review_id text NOT NULL REFERENCES reviews(id), branch_id text NOT NULL REFERENCES branches(id), analysis_run_id text NOT NULL REFERENCES analysis_runs(id), category text NOT NULL, aspect text NOT NULL, kind text NOT NULL, sentiment text NOT NULL, summary text NOT NULL, normalized_description text NOT NULL, evidence_quote text NOT NULL, start_offset integer, end_offset integer, provider text NOT NULL, mode text NOT NULL, model text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS observations_review_idx ON observations(review_id);
CREATE TABLE IF NOT EXISTS themes (id text PRIMARY KEY, business_id text NOT NULL REFERENCES businesses(id), branch_id text NOT NULL REFERENCES branches(id), title text NOT NULL, type text NOT NULL, status text NOT NULL DEFAULT 'suggested', priority text NOT NULL DEFAULT 'low', priority_reason text NOT NULL DEFAULT '', severity integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS theme_memberships (theme_id text NOT NULL REFERENCES themes(id), observation_id text NOT NULL UNIQUE REFERENCES observations(id), source text NOT NULL, confirmation text NOT NULL DEFAULT 'suggested', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(theme_id, observation_id));
CREATE TABLE IF NOT EXISTS tasks (id text PRIMARY KEY, theme_id text NOT NULL UNIQUE REFERENCES themes(id), branch_id text NOT NULL REFERENCES branches(id), title text NOT NULL, description text NOT NULL, assignee_role text NOT NULL, status text NOT NULL DEFAULT 'proposed', proposed_at timestamptz NOT NULL DEFAULT now(), approved_at timestamptz, resolved_at timestamptz, resolution_note text, approver text, approval_snapshot jsonb);
CREATE TABLE IF NOT EXISTS handoffs (id text PRIMARY KEY, approved_task_id text NOT NULL UNIQUE REFERENCES tasks(id), payload jsonb NOT NULL, simulated_status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS replies (id text PRIMARY KEY, review_id text NOT NULL UNIQUE REFERENCES reviews(id), task_id text NOT NULL REFERENCES tasks(id), theme_id text NOT NULL REFERENCES themes(id), text text NOT NULL, status text NOT NULL DEFAULT 'draft', provider text NOT NULL, mode text NOT NULL, model text, generated_at timestamptz NOT NULL DEFAULT now(), edited_at timestamptz, approved_at timestamptz, approver text);
CREATE TABLE IF NOT EXISTS activity_events (id text PRIMARY KEY, actor text NOT NULL, role text NOT NULL, type text NOT NULL, entity_type text NOT NULL, entity_id text NOT NULL, description text NOT NULL, metadata jsonb, created_at timestamptz NOT NULL DEFAULT now());
